/* Local learning progress and demo rewards only. This is not a real wallet. */
(()=>{const key='bunny-academy-v1',empty=()=>({version:1,lessonOne:{step:0,completed:false}});const read=()=>{try{const s=JSON.parse(localStorage.getItem(key)||'null');if(s?.version!==1||!Number.isInteger(s.lessonOne?.step)||s.lessonOne.step<0||s.lessonOne.step>7||typeof s.lessonOne.completed!=='boolean')return empty();return {version:1,lessonOne:{step:s.lessonOne.step,completed:s.lessonOne.completed}}}catch{return empty()}};const write=s=>{try{localStorage.setItem(key,JSON.stringify(s));return true}catch{return false}};window.BunnyAcademy={key,read,balance:()=>read().lessonOne.completed?100:0,saveStep(step){if(!Number.isInteger(step)||step<0||step>7)return false;const s=read();s.lessonOne.step=step;return write(s)},complete(){const s=read();if(s.lessonOne.step!==7)return {ok:false};const already=s.lessonOne.completed;s.lessonOne.completed=true;const ok=write(s);if(ok)try{localStorage.setItem('bunny-interface-guide-v1','seen')}catch{}return {ok,awarded:already?0:100}}}})();
